import pathlib,json,copy,yaml,subprocess,tempfile,shutil
class Strict(yaml.SafeLoader):pass
def mapping(loader,node,deep=False):
 loader.flatten_mapping(node);d={}
 for k,v in node.value:
  key=loader.construct_object(k,deep=deep)
  if key in d:raise ValueError('duplicate key')
  d[key]=loader.construct_object(v,deep=deep)
 return d
Strict.add_constructor(yaml.resolver.BaseResolver.DEFAULT_MAPPING_TAG,mapping)
def load(name):return yaml.load(pathlib.Path(name).read_text(encoding='utf-8'),Loader=Strict)

EXPECTED={'groups': [{'name': 'fractional-counter-increase', 'interval': '1m', 'rules': [{'record': 'instance:requests:increase3m', 'expr': 'increase(requests_total[3m])'}]}]}
FIXTURE={'rule_files': ['rules.yaml'], 'evaluation_interval': '1m', 'fuzzy_compare': True, 'tests': [{'interval': '1m', 'input_series': [{'series': 'requests_total{instance="normal"}', 'values': '100 101 102 104 107 108'}, {'series': 'requests_total{instance="reset"}', 'values': '100 102 1 3 5 6'}, {'series': 'requests_total{instance="idle"}', 'values': '0+0x5'}, {'series': 'requests_total{instance="one-point"}', 'values': '_ _ _ 10 _ _'}], 'promql_expr_test': [{'expr': 'instance:requests:increase3m', 'eval_time': '3m', 'exp_samples': [{'labels': 'instance:requests:increase3m{instance="normal"}', 'value': 4.5}, {'labels': 'instance:requests:increase3m{instance="reset"}', 'value': 4.5}, {'labels': 'instance:requests:increase3m{instance="idle"}', 'value': 0}]}, {'expr': 'instance:requests:increase3m', 'eval_time': '4m', 'exp_samples': [{'labels': 'instance:requests:increase3m{instance="normal"}', 'value': 7.5}, {'labels': 'instance:requests:increase3m{instance="reset"}', 'value': 5}, {'labels': 'instance:requests:increase3m{instance="idle"}', 'value': 0}]}, {'expr': 'instance:requests:increase3m', 'eval_time': '5m', 'exp_samples': [{'labels': 'instance:requests:increase3m{instance="normal"}', 'value': 6}, {'labels': 'instance:requests:increase3m{instance="reset"}', 'value': 4.5}, {'labels': 'instance:requests:increase3m{instance="idle"}', 'value': 0}]}]}]}
r=load('rules.yaml')
assert set(r)=={'groups'} and len(r['groups'])==1
g=r['groups'][0];assert set(g)=={'name','interval','rules'} and g['name']==EXPECTED['groups'][0]['name'] and g['interval']=='1m'
assert len(g['rules'])==len(EXPECTED['groups'][0]['rules'])
for actual,expected in zip(g['rules'],EXPECTED['groups'][0]['rules']):
 assert set(actual)==set(expected)
 assert {k:v for k,v in actual.items() if k!='expr'}=={k:v for k,v in expected.items() if k!='expr'}
 assert isinstance(actual['expr'],str) and actual['expr'].strip()

assert shutil.which('promtool'),'platform must supply native promtool'
with tempfile.TemporaryDirectory(prefix='trusted-prom-rules-') as tmp:
 fixture=copy.deepcopy(FIXTURE);fixture['rule_files']=[str(pathlib.Path('rules.yaml').resolve())]
 path=pathlib.Path(tmp)/'tests.yaml';path.write_text(yaml.safe_dump(fixture,sort_keys=False),encoding='utf-8')
 for args in [['promtool','check','rules','rules.yaml'],['promtool','test','rules',str(path)]]:
  p=subprocess.run(args,capture_output=True,text=True,encoding='utf-8',errors='replace',timeout=15)
  print(p.stdout);print(p.stderr);assert p.returncode==0,'native rule execution failed'
